examples.code:
.warn {
  color: red;
}
#main {
  background-color: yellow;
}

.box { color: green; }
p { color: blue; }
.c { color: orange; }
#x { color: red; }

.a { color: red; }
.b { color: #ff0000; }
.c { color: #f00; }
.d { color: rgb(255, 0, 0); }

.outer { font-size: 20px; }
.e { font-size: 2em; }
.r { font-size: 2rem; }
.p { font-size: 150%; }

.t {
  font-size: 20px;
  font-weight: bold;
  line-height: 1.5;
  text-align: center;
  text-decoration: underline;
}

div > p {
  color: red;
}
h1, h2 {
  color: blue;
}

.a, .b {
  width: 200px;
  padding: 20px;
  border: 5px solid black;
}
.b {
  box-sizing: border-box;
}

.box {
  padding: 10px 20px 30px 40px;
  margin: 5px 15px;
}

.card {
  width: 300px;
  margin: 0 auto;
  padding: 16px;
  border: 1px solid gray;
  border-radius: 8px;
  background-color: lightyellow;
}

span {
  width: 100px;
  height: 30px;
}
.b {
  display: inline-block;
}
.c {
  display: none;
}

.container {
  display: flex;
}
.item {
  width: 50px;
  height: 50px;
  background-color: lightblue;
}

.container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  width: 300px;
  height: 120px;
}
.item {
  width: 50px;
  height: 50px;
  background-color: lightblue;
}

.container {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  width: 200px;
}
.item {
  width: 80px;
  height: 50px;
  background-color: lightblue;
}

.container {
  display: flex;
  width: 300px;
}
.a {
  flex: 1;
}
.b {
  flex: 2;
}

body { margin: 0; }
.wrap {
  max-width: 600px;
  margin: 0 auto;
  background-color: lightyellow;
}

p {
  color: black;
}
@media (min-width: 600px) {
  p {
    color: red;
  }
}

.cards {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.card {
  padding: 16px;
  background-color: lightblue;
}
@media (min-width: 600px) {
  .cards {
    flex-direction: row;
  }
  .card {
    flex: 1;
  }
}
